.ds-secondary { background:var(--surface, #ffffff); color:var(--ink, #122030); border-color:var(--rule-strong, #96a5b4); }
.ds-secondary:hover { border-color:var(--ink, #122030); }
@media (hover:hover) and (prefers-reduced-motion:no-preference) { .ds-secondary:hover { transform:translateY(-1px); } }
.ds-secondary:active { transform:none; }

.ds-button { display:inline-flex; align-items:center; justify-content:center; gap:var(--s-2, 0.5rem); min-height:var(--tap, 48px); padding:0 var(--s-5, 1.25rem); border:1px solid transparent; border-radius:var(--r-1, 4px); font:650 1rem/1.2 var(--font, "Archivo", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif); text-decoration:none; cursor:pointer; transition:background-color .15s,border-color .15s,color .15s,transform .25s var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)),box-shadow .25s; }
@media (prefers-reduced-motion:reduce) { .ds-button { transition:none; } }
.ds-button:focus-visible { outline:3px solid var(--focus, #0f3d66); outline-offset:2px; }
.ds-ghost { width:var(--tap, 48px); padding:0; background:transparent; color:var(--ink, #122030); }
.ds-ghost:hover { color:var(--brand-ink, #165084); }
.ds-ghost svg { width:20px; height:20px; }

.ds-field { display:grid; gap:var(--s-1, 0.25rem); color:var(--ink, #122030); font:600 .9375rem/1.6 var(--font, "Archivo", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif); }
.ds-input { box-sizing:border-box; width:100%; min-height:var(--tap, 48px); padding:var(--s-3, 0.75rem); border:1px solid var(--rule-strong, #96a5b4); border-radius:var(--r-1, 4px); background:var(--surface, #ffffff); color:var(--ink, #122030); font:400 1rem/1.4 var(--font, "Archivo", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif); caret-color:var(--brand, #1f6aa8); }
.ds-input:hover { border-color:var(--ink-2, #2f3e4e); }
.ds-input:focus { outline:3px solid var(--focus, #0f3d66); outline-offset:1px; border-color:var(--ink, #122030); }
.ds-input[aria-invalid=true] { border-color:var(--error, #b42318); background:var(--error-wash, #fdeceb); }

.ds-nav { display:flex; flex-wrap:wrap; gap:var(--s-1, 0.25rem); background:var(--surface, #ffffff); border-bottom:1px solid var(--rule, #d2dbe3); }
.ds-nav-link { box-sizing:border-box; display:inline-flex; min-height:72px; align-items:center; padding:0 var(--s-3, 0.75rem); border-bottom:2px solid transparent; color:var(--ink, #122030); font:550 .9375rem/1.6 var(--font, "Archivo", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif); text-decoration:none; white-space:nowrap; }
.ds-nav-link:hover,.ds-nav-link[aria-current=page],.ds-nav-link[aria-current=location] { border-bottom-color:var(--brand, #1f6aa8); }
.ds-nav-link[aria-current=location] { color:var(--brand-ink, #165084); }
.ds-nav-link:focus-visible { outline:3px solid var(--focus, #0f3d66); outline-offset:-3px; }

.ds-contact { display:grid; gap:4px; align-content:start; padding:var(--s-5, 1.25rem); border:1px solid var(--rule, #d2dbe3); border-radius:16px; background:var(--surface, #ffffff); color:var(--ink, #122030); font:400 1rem/1.6 var(--font, "Archivo", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif); text-decoration:none; transition:transform .4s var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-contact-icon { width:46px; height:46px; display:grid; place-items:center; margin-bottom:var(--s-3, 0.75rem); border-radius:var(--r-3, 12px); background:var(--brand-wash, #e8f1f9); color:var(--brand-ink, #165084); }
.ds-contact-icon svg { width:22px; height:22px; }
.ds-contact strong { font-size:1.1875rem; font-weight:700; font-stretch:88%; line-height:1.3; }
.ds-contact-label { color:var(--brand-ink, #165084); font-size:var(--fs-label, 0.8125rem); font-weight:650; letter-spacing:.05em; text-transform:uppercase; }
.ds-contact-note { color:var(--brand-ink, #165084); font-size:var(--fs-small, 0.875rem); }
.ds-contact-go { display:inline-flex; align-items:center; gap:6px; margin-top:var(--s-3, 0.75rem); color:var(--brand-ink, #165084); font-size:var(--fs-small, 0.875rem); font-weight:650; }
.ds-contact-go svg { width:16px; height:16px; }
.ds-contact:hover { border-color:var(--brand, #1f6aa8); }
@media (hover:hover) and (prefers-reduced-motion:no-preference) { .ds-contact:hover { transform:translateY(-4px); } }
.ds-contact:focus-visible { outline:3px solid var(--focus, #0f3d66); outline-offset:2px; }
